290	    REG_WRITE(SOC_AON_RTC_REG_BASE+0x0*4, reg00);
291		REG_WRITE(SOC_AON_RTC_REG_BASE+0x1*4, reg01);
292		REG_WRITE(SOC_AON_RTC_REG_BASE+0x2*4, reg02);
293		return BK_OK;
294	}
