296	{
297	    uint32_t val= 0;
298	    val =  REG_READ(SOC_AON_RTC_REG_BASE+0x3*4);
299	
300	    while(val != REG_READ(SOC_AON_RTC_REG_BASE+0x3*4))
301	    {
302	        val = REG_READ(SOC_AON_RTC_REG_BASE+0x3*4);
303	    }
304	    return val;
305	}
