307	static inline uint32_t aon_rtc_ll_open_rtc_wakeup(uint32_t period)
308	{
309	    uint32_t wakeup_period= 0;
310		uint32_t rtc_int= 0;
311	
312	    wakeup_period = aon_rtc_ll_get_current_tick() + period;
313		REG_WRITE(SOC_AON_RTC_REG_BASE+0x2*4, wakeup_period);
314	
315		rtc_int =  REG_READ(SOC_AON_RTC_REG_BASE+0x0*4);
316		rtc_int |= BIT_AON_RTC_RTC_TICK_INT_EN;
317	
318		REG_WRITE(SOC_AON_RTC_REG_BASE+0x0*4, rtc_int);
319		return BK_OK;
